export default async function install(app){
const id=app.config.imageryLayerId,source=app.layers[id];app.assert(source,'No se encuentra Sentinel-2.');const left=app.getMount('copilot'),right=app.getMount('temporal'),clean=[],temp=[];let resultLayer=null,swipe=null,rows=[],mode='natural',busy=false;
const intents=['natural','vegetation','low_vigor','water','compare','change','explain','help'];const names={natural:'Color natural',vegetation:'Verdor relativo · NDVI',low_vigor:'NDVI bajo · lectura exploratoria',water:'Agua/humedad · NDWI',compare:'Comparación temporal NDVI',change:'Comparación temporal NDVI'};
function el(t,x,p){const n=document.createElement(t);if(x!==undefined)n.textContent=x;if(p)p.append(n);return n}function style(n,o){Object.assign(n.style,o);return n}function card(p){return style(el('div',undefined,p),{padding:'12px',border:'1px solid var(--app-border)',borderRadius:'12px',background:'var(--app-surface)'})}function note(p,x){return style(el('p',x,p),{margin:'5px 0 0',color:'var(--app-text-muted)',fontSize:'12px',lineHeight:'1.5'})}function button(p,x,fn,primary=false){const b=el('button',x,p);b.type='button';b.setAttribute('aria-label',x);style(b,{padding:'9px 11px',borderRadius:'9px',border:'1px solid var(--app-border)',background:primary?'var(--app-accent)':'var(--app-surface-raised)',color:primary?'white':'var(--app-text)',cursor:'pointer',font:'inherit',textAlign:'left'});const f=()=>fn();b.addEventListener('click',f);clean.push(()=>b.removeEventListener('click',f));return b}
style(left,{display:'flex',flexDirection:'column',gap:'11px',minWidth:'0',font:'inherit'});style(right,{display:'flex',flexDirection:'column',gap:'10px',minWidth:'0',font:'inherit'});source.visible=true;const intro=card(left);style(el('div','COPILOTO · HUERTA DE MURCIA',intro),{color:'var(--app-accent)',fontSize:'10px',letterSpacing:'1.5px',fontWeight:'700'});style(el('p','Explora visualmente el verdor de la huerta metropolitana, contrasta sectores y revisa cambios entre fechas con Sentinel‑2. NDVI y NDWI son indicadores espectrales: no identifican cultivos ni diagnostican su estado.',intro),{margin:'8px 0 0',lineHeight:'1.5',fontSize:'13px'});
const feed=style(el('div',undefined,left),{display:'flex',flexDirection:'column',gap:'7px',maxHeight:'210px',overflowY:'auto'});function bubble(x,user=false){const n=el('div',x,feed);style(n,{padding:'9px',borderRadius:'9px',lineHeight:'1.45',fontSize:'12px',whiteSpace:'pre-wrap',background:user?'color-mix(in srgb, var(--app-accent) 18%, var(--app-surface))':'var(--app-surface-raised)',border:'1px solid var(--app-border)'});feed.scrollTop=feed.scrollHeight}bubble('¡Hola! Estamos en la huerta del entorno de Murcia. Prueba “verdor de la huerta”, “compara sectores”, “agua o humedad”, “color natural” o “compara fechas”. Para sectores, la lectura es visual; no calcula estadísticas por parcela.');
const form=style(el('form',undefined,left),{display:'flex',flexDirection:'column',gap:'7px'}),input=el('textarea',undefined,form);input.rows=3;input.placeholder='Ej.: compara visualmente los sectores de huerta…';input.setAttribute('aria-label','Pregunta al copiloto');style(input,{resize:'vertical',minHeight:'62px',padding:'9px',borderRadius:'9px',border:'1px solid var(--app-border)',background:'var(--app-surface-raised)',color:'var(--app-text)',font:'inherit'});const send=button(form,'Aplicar al mapa ↗',()=>{},true);send.type='submit';const chips=style(el('div',undefined,left),{display:'flex',flexWrap:'wrap',gap:'6px'});for(const x of ['Verdor de la huerta','Compara sectores','Agua / humedad','Color natural','Compara fechas'])button(chips,x,()=>{input.value=x;app.actions.invoke('interpret-request',{text:x})});const rb=card(left);style(el('div','LECTURA DEL MAPA',rb),{fontSize:'10px',fontWeight:'700',letterSpacing:'1.3px',color:'var(--app-text-muted)'});const answer=style(el('p','Color natural Sentinel‑2. Elige una lectura espectral o compara escenas.',rb),{margin:'7px 0 0',fontSize:'12px',lineHeight:'1.5'});note(left,'La interpretación funciona con reglas locales, sin LLM. Las diferencias visuales pueden depender de cultivo, calendario, suelo, agua, atmósfera, sombras o nubes.');
const panel=card(right);style(el('div','COMPARACIÓN TEMPORAL · SENTINEL‑2',panel),{color:'var(--app-accent)',fontSize:'10px',letterSpacing:'1.4px',fontWeight:'700'});style(el('p','Busca escenas que cubran la vista actual de Murcia. Se muestran fechas del mismo tile para hacer una comparación temporal coherente. La nubosidad es un dato de escena, no una máscara por píxel.',panel),{margin:'7px 0 0',fontSize:'12px',lineHeight:'1.45'});const status=note(panel,'Consulta el catálogo para cargar escenas del área visible.');const catalog=button(panel,'Buscar escenas en la vista',()=>app.actions.invoke('load-scene-catalog',{}),true);const controls=style(el('div',undefined,right),{display:'grid',gap:'7px'});function select(label){const l=style(el('label',undefined,controls),{display:'flex',flexDirection:'column',gap:'4px',fontSize:'11px',color:'var(--app-text-muted)'});el('span',label,l);const s=el('select',undefined,l);style(s,{width:'100%',minWidth:'0',padding:'8px',borderRadius:'8px',border:'1px solid var(--app-border)',background:'var(--app-surface-raised)',color:'var(--app-text)',font:'inherit'});s.disabled=true;return s}const dateA=select('Fecha inicial'),dateB=select('Fecha de comparación'),compare=button(right,'Comparar NDVI con deslizador',()=>app.actions.invoke('compare-scenes',{a:dateA.value,b:dateB.value}),true);compare.disabled=true;const temporal=note(right,'La comparación con Swipe es visual; no calcula una diferencia raster ni delimita cambios automáticamente.');const sourceCard=card(right);style(el('div','CÓMO INTERPRETARLO',sourceCard),{fontWeight:'700',fontSize:'10px',letterSpacing:'1.2px'});note(sourceCard,'NDVI resume verdor relativo; no determina especie, cultivo, rendimiento, necesidad de riego ni salud vegetal. NDWI es una señal espectral exploratoria y no confirma agua disponible. La nubosidad indicada corresponde a la escena completa.');
function clearCompare(){if(swipe){try{app.view.ui.remove(swipe);swipe.destroy()}catch(_){}swipe=null}for(const l of temp.splice(0)){try{app.map.remove(l)}catch(_){}}if(resultLayer)resultLayer.visible=true}
async function buildLowVigor(){clearCompare();mode='low_vigor';const rf=await app.import('esri/layers/support/rasterFunctionUtils');const ndvi=rf.bandArithmeticNDVI({nirBandId:7,redBandId:3,scientificOutput:true});const remap=rf.remap({raster:ndvi,rangeMaps:[{range:[-1,0.2],output:1},{range:[0.2,0.45],output:2},{range:[0.45,1],output:3}],allowUnmatched:false});const color=rf.colormap({raster:remap,colormap:[[1,220,38,38],[2,245,158,11],[3,34,197,94]]});if(!resultLayer){resultLayer=source.clone();resultLayer.id='espectra-current-imagery';app.map.add(resultLayer)}source.visible=false;resultLayer.visible=true;resultLayer.title='Huerta de Murcia · clases NDVI orientativas';resultLayer.rasterFunction=color;answer.textContent='Clases demostrativas de NDVI: rojo <0,20; ámbar 0,20–0,45; verde ≥0,45. No son una clasificación de cultivos ni un diagnóstico: suelo, agua, sombra, atmósfera, nubes y calendario agrícola influyen. Contrasta solo fechas y sectores comparables; los umbrales requieren validación local.';return{intent:'low_vigor',thresholds:[-1,0.2,0.45,1]}}
function setMode(m){clearCompare();mode=m;const functions={natural:'Natural Color with DRA',vegetation:'NDVI Colormap',water:'NDWI Raw'};if(!resultLayer){resultLayer=source.clone();resultLayer.id='espectra-current-imagery';app.map.add(resultLayer)}source.visible=false;resultLayer.visible=true;resultLayer.title='Huerta de Murcia · '+names[m];resultLayer.rasterFunction={rasterFunction:functions[m]};const explain={natural:'Composición de color natural (bandas visibles 4‑3‑2) para situar visualmente la huerta; no es una clasificación.',vegetation:'NDVI aplicado. Úsalo para comparar el verdor relativo entre sectores o fechas; no diagnostica salud ni identifica cultivos.',water:'NDWI aplicado como indicador espectral exploratorio. No confirma humedad del suelo, agua disponible o riego.'};answer.textContent=explain[m]}
function sceneName(s){return new Date(Number(s.acquisitiondate)).toLocaleDateString('es-ES',{year:'numeric',month:'short',day:'2-digit',timeZone:'UTC'})+' · '+s.tilename+' · nubosidad '+(Number.isFinite(Number(s.cloudcover))?(100*Number(s.cloudcover)).toFixed(1)+'%':'s/d')}function sceneRule(s){return{method:'lock-raster',lockRasterIds:[Number(s.objectid)]}}function fold(s){return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9\s]/g,' ').replace(/\s+/g,' ').trim()}function intent(s){const t=fold(s);if(/menor vigor|bajo vigor|poco vigor|ndvi bajo|vegetacion debil/.test(t))return'low_vigor';if(/agua|hidric|humed|inund|ndwi|riego/.test(t))return'water';if(/compara.*(fecha|ano|mes|estacion|temporal)|compar.*(fecha|temporal)|cambio.*temporal|evolucion|entre fechas|serie temporal/.test(t))return'compare';if(/sector|zona|parcel|huerta|verdor|veget|vigor|ndvi|cultivo/.test(t))return'vegetation';if(/explica|interpreta|que veo|que estoy viendo|mapa/.test(t))return'explain';if(/natural|rgb|color verdadero/.test(t))return'natural';if(/compara|compar/.test(t))return'vegetation';return'help'}function fill(sel,data){sel.replaceChildren();for(const s of data){const o=el('option',sceneName(s));o.value=String(s.objectid);sel.append(o)}sel.disabled=!data.length}
app.actions.register('load-scene-catalog',async()=>{if(busy)return;busy=true;catalog.disabled=true;status.textContent='Consultando escenas sobre Murcia…';try{const q=source.createQuery();q.geometry=app.view.extent;q.outFields=['objectid','acquisitiondate','cloudcover','tilename','category'];q.returnGeometry=false;q.num=500;q.orderByFields=['acquisitiondate DESC'];q.where='category = 1 AND cloudcover <= 0.20';const r=await source.queryRasters(q),seen=new Set();rows=r.features.map(f=>f.attributes).filter(s=>s&&Number.isFinite(Number(s.objectid))&&Number.isFinite(Number(s.acquisitiondate))&&s.tilename).filter(s=>{if(seen.has(String(s.objectid)))return false;seen.add(String(s.objectid));return true}).sort((a,b)=>Number(b.acquisitiondate)-Number(a.acquisitiondate));const counts=new Map();for(const s of rows)counts.set(s.tilename,(counts.get(s.tilename)||0)+1);const tile=[...counts.entries()].sort((a,b)=>b[1]-a[1])[0]?.[0],same=rows.filter(s=>s.tilename===tile);fill(dateA,same);fill(dateB,same);if(same.length){const old=same.find(s=>Number(s.acquisitiondate)<Number(same[0].acquisitiondate)-45*86400000)||same[1]||same[0];dateA.value=String(old.objectid);dateB.value=String(same[0].objectid)}compare.disabled=same.length<2;status.textContent=same.length+' escenas del tile '+(tile||'sin tile')+' con nubosidad de escena ≤20% (en la vista: '+rows.length+').';return{scenes:rows.length,tile:tile||null,selected: same.length?[{objectid:Number(dateA.value),date:new Date(Number(same.find(s=>String(s.objectid)===dateA.value).acquisitiondate)).toISOString()},{objectid:Number(dateB.value),date:new Date(Number(same.find(s=>String(s.objectid)===dateB.value).acquisitiondate)).toISOString()}]:[]}}catch(e){status.textContent='No se pudo consultar el catálogo: '+String(e.message||e).slice(0,120);return{error:String(e.message||e).slice(0,120)}}finally{busy=false;catalog.disabled=false}});
app.actions.register('compare-scenes',async({a,b}={})=>{const sa=rows.find(s=>String(s.objectid)===String(a)),sb=rows.find(s=>String(s.objectid)===String(b));if(!sa||!sb||Number(sa.objectid)===Number(sb.objectid)||sa.tilename!==sb.tilename){bubble('Selecciona dos escenas distintas del mismo tile Sentinel‑2.');return{compared:false}}clearCompare();source.visible=false;mode='change';const Swipe=await app.import('esri/widgets/Swipe');function dated(s,k){const l=source.clone();l.id='espectra-compare-'+k;l.title='NDVI · '+sceneName(s);l.mosaicRule=sceneRule(s);l.rasterFunction={rasterFunction:'NDVI Colormap'};l.visible=true;app.map.add(l);temp.push(l);return l}const la=dated(sa,'a'),lb=dated(sb,'b');if(resultLayer)resultLayer.visible=false;await Promise.all([la.load(),lb.load()]);swipe=new Swipe({view:app.view,leadingLayers:[lb],trailingLayers:[la],position:50,direction:'horizontal'});app.view.ui.add(swipe,'manual');answer.textContent='Comparación visual de NDVI para '+sceneName(sa)+' y '+sceneName(sb)+'. Desliza para contrastar la huerta entre fechas; esto no calcula diferencias raster ni detecta causas.';temporal.textContent='Escenas fijadas por ID de raster: '+sa.objectid+' y '+sb.objectid+'. Las variaciones visuales pueden reflejar fenología, labores, humedad, atmósfera, geometría de observación o nubes residuales.';bubble('Comparación temporal lista: '+sceneName(sa)+' frente a '+sceneName(sb)+'.');return{compared:true,tile:sa.tilename,a:Number(sa.acquisitiondate),b:Number(sb.acquisitiondate),objectIds:[Number(sa.objectid),Number(sb.objectid)],rules:[la.mosaicRule.toJSON(),lb.mosaicRule.toJSON()],swipe:!!swipe}});
app.actions.register('interpret-request',async({text}={})=>{const q=String(text||'').slice(0,500);if(!q.trim())return{intent:'empty'};bubble(q,true);const i=intent(q);if(i==='help'){const msg='Puedo mostrar color natural, verdor relativo (NDVI), clases orientativas de NDVI, NDWI o comparación visual entre dos fechas. Para comparar sectores, aplica NDVI y explora la vista; no hay estadísticas de parcela.';bubble(msg);answer.textContent=msg;return{intent:i}}if(i==='explain'){bubble(answer.textContent);return{intent:i,activeMode:mode}}if(i==='compare'||i==='change'){if(rows.length<2){bubble('Primero pulsa “Buscar escenas en la vista” para encontrar fechas de Murcia.');return{intent:'compare',needsCatalog:true}}return await app.actions.invoke('compare-scenes',{a:dateA.value,b:dateB.value})}if(i==='low_vigor')return await buildLowVigor();if(i==='vegetation'){setMode('vegetation');const msg='NDVI aplicado. Compara visualmente sectores de huerta en la vista con cautela: la escala no representa parcelas ni distingue cultivos, y el resultado no es diagnóstico.';bubble(msg);return{intent:i,rasterFunction:'NDVI Colormap'}}if(i==='water'){setMode('water');bubble('NDWI aplicado como indicador espectral exploratorio; no confirma riego, humedad del suelo ni agua disponible.');return{intent:i,rasterFunction:'NDWI Raw'}}setMode('natural');bubble('Composición de color natural aplicada para contexto visual.');return{intent:'natural',rasterFunction:'Natural Color with DRA'}});
const submitHandler=e=>{e.preventDefault();const t=input.value.trim();input.value='';app.actions.invoke('interpret-request',{text:t})};form.addEventListener('submit',submitHandler);clean.push(()=>form.removeEventListener('submit',submitHandler));app.onCleanup(()=>{clearCompare();if(resultLayer){try{app.map.remove(resultLayer)}catch(_){}resultLayer=null}source.visible=true;for(const f of clean.splice(0)){try{f()}catch(_){}}left.replaceChildren();right.replaceChildren()});return{layerId:id,area:app.config.areaName,intents,modes:['Natural Color with DRA','NDVI Colormap','NDWI Raw','clases NDVI exploratorias'],actions:['interpret-request','load-scene-catalog','compare-scenes']}}
